        ("TestScanWindowAdvancing", "test_backlog_restarts_when_max_pages_increased"),
    ],
}

for path, specs in targets.items():
    head_src = subprocess.run(["git", "show", f"HEAD:{path}"], capture_output=True, text=True).stdout
    head_lines = head_src.split("\n")
    head_tree = ast.parse(head_src)
    snippets = {}
    for cls in [n for n in head_tree.body if isinstance(n, ast.ClassDef)]:
        for fn in [n for n in cls.body if isinstance(n, ast.FunctionDef)]:
            for want_cls, want_fn in specs:
                if cls.name == want_cls and fn.name == want_fn:
                    start = fn.lineno - 1
                    for dec in getattr(fn, "decorator_list", []):
                        start = min(start, dec.lineno - 1)
                    snippets[(want_cls, want_fn)] = "\n".join(head_lines[start:fn.end_lineno])

    cur_src = pathlib.Path(path).read_text()
    cur_lines = cur_src.split("\n")
    cur_tree = ast.parse(cur_src)
    inserts = []
    for (want_cls, want_fn), snippet in snippets.items():
        cls_node = next(n for n in cur_tree.body if isinstance(n, ast.ClassDef) and n.name == want_cls)
        inserts.append((cls_node.end_lineno, snippet, want_fn))
    for end_line, snippet, name in sorted(inserts, reverse=True):
        cur_lines[end_line:end_line] = ["", snippet]
        print(f"{path}: restored {name} at line {end_line}")
    pathlib.Path(path).write_text("\n".join(cur_lines))
